import { bn } from '@/shared/lib/bn';
import { tr } from '@/shared/lib/i18n';
import { pick, Q, wrongs } from './q';
import type { Generator, LevelBank } from './types';

/* Our own questions for chapter 3 (levels 8–15). First option is always right. */
const n = (v: number) => bn(v);
const d = (v: number) => bn(v, { grouping: false });
/** millions in Bangla words: 5 → ৫০ লাখ, 20 → ২ কোটি */
const mil = (m: number) => (m >= 10 ? `${n(m / 10)} কোটি` : `${n(m * 10)} লাখ`);

const codeLen: Generator = {
  id: 'l8-g1', concept: 'chars',
  make: (rand) => {
    const [label, enLabel, count] = pick(rand, [
      ['১০ লাখ', '1 million', 1e6], ['১০ কোটি', '100 million', 1e8], ['১,০০০ কোটি', '10 billion', 1e10],
      ['১ লাখ কোটি', '1 trillion', 1e12], ['২০০ কোটি', '2 billion', 2e9],
    ] as const);
    let k = 1; while (62 ** k < count) k++;
    return {
      prompt: tr(`${label}টা link রাখতে base62 code-এ কমপক্ষে কয় অক্ষর লাগে?`, `What is the shortest base62 code that covers ${enLabel} links?`),
      options: [n(k), ...wrongs(k, [k - 1, k + 1, k + 2, k - 2]).map(n)],
      explain: tr(`৬২^${n(k - 1)} < ${label} ≤ ৬২^${n(k)}, তাই ${n(k)} অক্ষর।`, `62^${n(k - 1)} < ${enLabel} ≤ 62^${n(k)}, so ${n(k)} characters.`),
    };
  },
};
const crawlRate: Generator = {
  id: 'l9-g1', concept: 'scale',
  make: (rand) => {
    const b = pick(rand, [1, 2, 5, 10, 15]);
    const right = Math.round((b * 1e9) / 2_592_000);
    const opts = wrongs(right, [Math.round((b * 1e9) / 86400), Math.round(right / 10), right * 7]);
    return {
      prompt: tr(`মাসে ${n(b * 100)} কোটি পাতা crawl করতে হবে। গড়ে সেকেন্ডে কয়টা পাতা?`, `You must crawl ${n(b)} billion pages a month. About how many pages a second?`),
      options: [`~${n(right)}`, ...opts.map((o) => `~${n(o)}`)],
      explain: tr(`${n(b * 100)} কোটি ÷ (৩০ × ৮৬,৪০০ সেকেন্ড) ≈ ${n(right)}। Peak-এর জন্য আরও বেশি রাখুন।`, `${n(b)} billion ÷ (30 × 86,400 s) ≈ ${n(right)}. Plan more for peaks.`),
    };
  },
};
const workers: Generator = {
  id: 'l10-g1', concept: 'workers',
  make: (rand) => {
    const peak = pick(rand, [2000, 5000, 12000]), per = pick(rand, [50, 100, 200]);
    const right = Math.ceil(peak / per);
    return {
      prompt: tr(`Peak-এ সেকেন্ডে ${n(peak)}টা notification। একটা worker সেকেন্ডে ${n(per)}টা পাঠায়। কমপক্ষে কয়টা worker?`, `At peak, ${n(peak)} notifications a second. One worker sends ${n(per)} a second. How many workers at least?`),
      options: [n(right), ...wrongs(right, [Math.ceil(peak / (per * 10)), right * 2, Math.ceil(right / 2), right + 10]).map(n)],
      explain: tr(`${n(peak)} ÷ ${n(per)} = ${n(right)}; বাস্তবে একটু বাড়তি রাখুন।`, `${n(peak)} ÷ ${n(per)} = ${n(right)}; keep some headroom in practice.`),
    };
  },
};
const fanoutWrites: Generator = {
  id: 'l11-g1', concept: 'fanout',
  make: (rand) => {
    const f = pick(rand, [300, 2000, 50000]), p = pick(rand, [2, 5, 10]);
    const right = f * p;
    return {
      prompt: tr(`${n(f)} follower-এর একজন দিনে ${n(p)}টা post করেন। Push মডেলে দিনে কয়টা feed-লেখা?`, `Someone with ${n(f)} followers posts ${n(p)} times a day. How many feed writes a day under push?`),
      options: [n(right), ...wrongs(right, [f, right * 10, f + p, p * 100]).map(n)],
      explain: tr(`প্রতিটা post প্রতিটা follower-এর feed-এ: ${n(f)} × ${n(p)} = ${n(right)}।`, `Each post lands in every follower's feed: ${n(f)} × ${n(p)} = ${n(right)}.`),
    };
  },
};
const beats: Generator = {
  id: 'l12-g1', concept: 'presence',
  make: (rand) => {
    const [h, t] = pick(rand, [[5, 30], [10, 30], [15, 30], [5, 20], [10, 60], [15, 90]] as const);
    const right = t / h;
    return {
      prompt: tr(`Heartbeat প্রতি ${n(h)} সেকেন্ডে, ${n(t)} সেকেন্ড চুপ থাকলে offline। পরপর কয়টা heartbeat হারালে offline?`, `A heartbeat every ${n(h)} s; ${n(t)} s of silence means offline. How many beats in a row must go missing?`),
      options: [n(right), ...wrongs(right, [1, t, right * 2, right + 3]).map(n)],
      explain: tr(`${n(t)} ÷ ${n(h)} = ${n(right)}টা; একটা হারালেই offline দেখালে অবস্থা কাঁপতে থাকে।`, `${n(t)} ÷ ${n(h)} = ${n(right)}; going offline on a single miss would make status flicker.`),
    };
  },
};
const typeahead: Generator = {
  id: 'l13-g1', concept: 'aggregator',
  make: (rand) => {
    const d = pick(rand, [5, 10, 20]), s = pick(rand, [5, 10]), c = pick(rand, [10, 20]);
    const x = (d * 1e6 * s * c) / 86400;
    const right = Math.round(x / 1000) * 1000;
    return {
      prompt: tr(`${mil(d)} DAU, প্রত্যেকে দিনে ${n(s)}টা search, গড়ে ${n(c)} অক্ষর, প্রতি অক্ষরে একটা request। সেকেন্ডে কত?`, `${n(d)} million DAU, ${n(s)} searches each a day, ${n(c)} characters on average, one request per character. Requests a second?`),
      options: [`~${n(right)}`, ...wrongs(right, [Math.round(x / c / 100) * 100, right * 10, Math.round(right / 24 / 10) * 10]).map((o) => `~${n(o)}`)],
      explain: tr(`${mil(d)} × ${n(s)} × ${n(c)} ÷ ৮৬,৪০০ ≈ ${n(right)}।`, `${n(d)}M × ${n(s)} × ${n(c)} ÷ 86,400 ≈ ${n(right)}.`),
    };
  },
};
const cdnCost: Generator = {
  id: 'l14-g1', concept: 'cdn',
  make: (rand) => {
    const v = pick(rand, [1, 5, 10]), mb = pick(rand, [100, 200, 500]), p = pick(rand, [0.02, 0.05]);
    const right = Math.round(v * mb * p * 1000);
    const money = (x: number) => `$${n(x)}`;
    return {
      prompt: tr(`দিনে ${mil(v)} view, প্রতিটায় ${n(mb)} MB, CDN প্রতি GB-তে $${d(p)}। দিনের CDN খরচ কত?`, `${n(v)} million views a day, ${n(mb)} MB each, the CDN costs $${d(p)} per GB. The daily CDN bill?`),
      options: [money(right), ...wrongs(right, [right * 1000, Math.round(right / 10), right * 30]).map(money)],
      explain: tr(`${mil(v)} × ${d(mb / 1000)} GB × $${d(p)} = $${n(right)}; জনপ্রিয় video-ই এই খরচের বেশিরভাগ।`, `${n(v)}M × ${d(mb / 1000)} GB × $${d(p)} = $${n(right)}; popular videos make up most of it.`),
    };
  },
};
const blocksLeft: Generator = {
  id: 'l15-g1', concept: 'resume',
  make: (rand) => {
    const size = pick(rand, [100, 200, 400, 1000]);
    const total = size / 4, done = 5 + Math.floor(rand() * 16);
    const right = total - done;
    return {
      prompt: tr(`${n(size)} MB file, ৪ MB-র block। ${n(done)}টা block যাওয়ার পর network গেল। Resume করলে আর কয়টা block?`, `A ${n(size)} MB file in 4 MB blocks. The network drops after ${n(done)} blocks. With resume, how many blocks are left?`),
      options: [n(right), ...wrongs(right, [total, done, right * 2, right + 4]).map(n)],
      explain: tr(`মোট ${n(size)} ÷ ৪ = ${n(total)}টা; ${n(done)}টা পৌঁছেছে, বাকি ${n(right)}।`, `${n(size)} ÷ 4 = ${n(total)} blocks; ${n(done)} arrived, ${n(right)} remain.`),
    };
  },
};

